/// Weakly Compressible SPH pressure computation via the Tait equation of state.
#[derive(Debug, Clone)]
pub struct WcSphPressure {
    /// Rest density (kg/m³).
    pub rho0: f64,
    /// Reference speed of sound (m/s).
    pub c0: f64,
    /// Tait exponent (typically 7 for water).
    pub gamma: f64,
}
impl WcSphPressure {
    /// Create a new `WcSphPressure` instance.
    pub fn new(rho0: f64, c0: f64, gamma: f64) -> Self {
        Self { rho0, c0, gamma }
    }
    /// Compute pressure from density using the Tait EOS.
    pub fn pressure(&self, rho: f64) -> f64 {
        tait_eos(rho, self.rho0, self.c0, self.gamma)
    }
    /// CFL-limited time step for sound-speed constraint.
    ///
    /// `dt = 0.4 * h / c0`
    pub fn cfl_dt(&self, h: f64) -> f64 {
        0.4 * h / self.c0
    }
    /// Alias for [`cfl_dt`](Self::cfl_dt).
    pub fn sound_speed_cfl_dt(&self, h: f64) -> f64 {
        self.cfl_dt(h)
    }
}
/// Incompressible SPH (ISPH) — projection-based pressure solver (simplified).
///
/// Solves a pressure Poisson equation (PPE) to enforce divergence-free velocity.
#[derive(Debug, Clone)]
pub struct IsphPressure {
    /// Rest density (kg/m³).
    pub rho0: f64,
}
impl IsphPressure {
    /// Create a new `IsphPressure` instance.
    pub fn new(rho0: f64) -> Self {
        Self { rho0 }
    }
    /// Compute the velocity divergence at particle `i` using SPH summation.
    ///
    /// `div(v)_i = Σ_j (m_j/ρ_j) (v_j − v_i) · ∇ᵢW_ij`
    ///
    /// with the exact gradient of the cubic-spline kernel,
    /// `∇ᵢW_ij = W'(r) (x_i − x_j)/r` (`W' ≤ 0`, compact support `2h`), which
    /// points from particle `i` towards neighbour `j`.  An expanding flow
    /// (`v = α x`) gives `div ≈ 3α > 0`, a converging one a negative value, and
    /// uniform or rigidly rotating flow gives zero.
    ///
    /// This scans all particles (`O(N)`);
    /// [`divergence_velocity_all`](Self::divergence_velocity_all) evaluates
    /// every particle in `O(N k)`.
    pub fn divergence_velocity(
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        h: f64,
        i: usize,
    ) -> f64 {
        let pi = positions[i];
        let vi = velocities[i];
        let mut div = 0.0_f64;
        for (j, (pj, vj)) in positions.iter().zip(velocities.iter()).enumerate() {
            if j != i {
                let volume_j = masses[j] / densities[j].max(1e-20);
                div += volume_j * relative_velocity_dot_gradient(pi, vi, *pj, *vj, h);
            }
        }
        div
    }
    /// The velocity divergence [`divergence_velocity`](Self::divergence_velocity)
    /// of every particle.
    ///
    /// The neighbours are found once with a spatial hash, so the cost is
    /// `O(N k)` for `k` neighbours per particle.
    pub fn divergence_velocity_all(
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        h: f64,
    ) -> Vec<f64> {
        let n = positions.len();
        let neighbors = support_neighbors(positions, h);
        (0..n)
            .map(|i| {
                let mut div = 0.0_f64;
                for &j in neighbor_row(&neighbors, i) {
                    if j == i || j >= n {
                        continue;
                    }
                    let volume_j = masses[j] / densities[j].max(1e-20);
                    div += volume_j
                        * relative_velocity_dot_gradient(
                            positions[i],
                            velocities[i],
                            positions[j],
                            velocities[j],
                            h,
                        );
                }
                div
            })
            .collect()
    }
    /// One Jacobi iteration for the pressure Poisson equation.
    ///
    /// Solves `A p = rhs` where `aij` encodes the off-diagonal coefficients
    /// and the diagonal is inferred as `- Σ_j a_ij` (standard Laplacian form).
    ///
    /// Returns the updated pressure vector.
    pub fn pressure_poisson_jacobi_step(
        pressures: &[f64],
        rhs: &[f64],
        aij: &[Vec<(usize, f64)>],
    ) -> Vec<f64> {
        let n = pressures.len();
        let mut p_new = vec![0.0_f64; n];
        for i in 0..n {
            let diag: f64 = -aij[i].iter().map(|&(_, a)| a).sum::<f64>();
            if diag.abs() < 1e-14 {
                p_new[i] = pressures[i];
                continue;
            }
            let off: f64 = aij[i].iter().map(|&(j, a)| a * pressures[j]).sum();
            p_new[i] = (rhs[i] - off) / diag;
        }
        p_new
    }
}
/// Predictive-Corrective Incompressible SPH (PCISPH) pressure solver.
///
/// Reference: Solenthaler & Pajarola 2009.
#[derive(Debug, Clone)]
pub struct PciSph {
    /// Rest density (kg/m³).
    pub rho0: f64,
    /// Pressure correction scaling factor δ.
    pub delta: f64,
}
impl PciSph {
    /// Build a `PciSph` instance for particles of mass `mass` at rest density
    /// `rho0`, smoothing length `h` and time step `dt`.
    ///
    /// `delta` is the lattice-based pressure-correction factor
    /// [`pcisph_delta`].  It scales with `1/dt²` and depends on the mass, so
    /// assign [`compute_delta`](Self::compute_delta) to `delta` (or build a new
    /// instance) when the time step changes.
    pub fn new(rho0: f64, h: f64, dt: f64, mass: f64) -> Self {
        let delta = Self::compute_delta(h, rho0, dt, mass);
        Self { rho0, delta }
    }
    /// The pressure-correction factor `δ` of Solenthaler & Pajarola (2009) for
    /// particles of mass `mass`, rest density `rho0`, smoothing length `h` and
    /// time step `dt`: [`pcisph_delta`].
    pub fn compute_delta(h: f64, rho0: f64, dt: f64, mass: f64) -> f64 {
        pcisph_delta(rho0, h, dt, mass)
    }
    /// Euler-forward density prediction: `rho_i + drho_dt * dt`.
    pub fn predict_density(&self, rho: f64, drho_dt: f64, dt: f64) -> f64 {
        rho + drho_dt * dt
    }
    /// Density error: `rho_pred - rho0`.
    pub fn density_error(&self, rho_pred: f64) -> f64 {
        rho_pred - self.rho0
    }
    /// Pressure correction step: `p += delta * rho_error`.
    pub fn pressure_update(&self, p: f64, rho_error: f64) -> f64 {
        p + self.delta * rho_error
    }
    /// Check convergence: `max |rho_error| < tol * rho0`.
    pub fn converged(&self, rho_errors: &[f64], tol: f64) -> bool {
        rho_errors.iter().map(|e| e.abs()).fold(0.0_f64, f64::max) < tol * self.rho0
    }
}
/// Tracks solver performance history and recommends the best solver.
pub struct ResidualBasedSelector {
    /// Performance history.
    pub history: Vec<SolverPerformanceEntry>,
    /// Maximum history size.
    pub max_history: usize,
}
impl ResidualBasedSelector {
    /// Create a new selector.
    pub fn new(max_history: usize) -> Self {
        Self {
            history: Vec::new(),
            max_history,
        }
    }
    /// Record a solver performance entry.
    pub fn record(&mut self, entry: SolverPerformanceEntry) {
        self.history.push(entry);
        if self.history.len() > self.max_history {
            self.history.remove(0);
        }
    }
    /// Recommend the solver with the lowest average residual.
    pub fn recommend(&self) -> SolverType {
        if self.history.is_empty() {
            return SolverType::Wcsph;
        }
        let mut wcsph_sum = 0.0_f64;
        let mut wcsph_count = 0_usize;
        let mut pcisph_sum = 0.0_f64;
        let mut pcisph_count = 0_usize;
        let mut iisph_sum = 0.0_f64;
        let mut iisph_count = 0_usize;
        for e in &self.history {
            match e.solver_type {
                SolverType::Wcsph => {
                    wcsph_sum += e.residual;
                    wcsph_count += 1;
                }
                SolverType::Pcisph => {
                    pcisph_sum += e.residual;
                    pcisph_count += 1;
                }
                SolverType::Iisph => {
                    iisph_sum += e.residual;
                    iisph_count += 1;
                }
            }
        }
        let avg = |sum: f64, count: usize| -> f64 {
            if count == 0 {
                f64::MAX
            } else {
                sum / count as f64
            }
        };
        let wcsph_avg = avg(wcsph_sum, wcsph_count);
        let pcisph_avg = avg(pcisph_sum, pcisph_count);
        let iisph_avg = avg(iisph_sum, iisph_count);
        if wcsph_avg <= pcisph_avg && wcsph_avg <= iisph_avg {
            SolverType::Wcsph
        } else if pcisph_avg <= iisph_avg {
            SolverType::Pcisph
        } else {
            SolverType::Iisph
        }
    }
    /// Number of entries recorded.
    pub fn history_len(&self) -> usize {
        self.history.len()
    }
}
/// Result of a DFSPH pressure pass, see [`DfsphSolverSimple::divergence_free_solve`]
/// and [`DfsphSolverSimple::density_invariant_solve`].
#[derive(Debug, Clone)]
pub struct DfsphPassResult {
    /// Accumulated pressure `pᵢ = κᵢ ρᵢ` of every particle \[Pa\]; never negative.
    pub pressures: Vec<f64>,
    /// The input velocities with the pressure accelerations of the pass applied
    /// \[m s⁻¹\].
    pub velocities: Vec<[f64; 3]>,
    /// Number of passes of the loop (at most `max_iter_density`); the pass that
    /// finds the constraint satisfied counts as well.
    pub iterations: usize,
    /// Residual of every evaluated state.  Entry 0 belongs to the input
    /// velocities, entry `k` to the state after `k` corrections.
    pub residual_history: Vec<f64>,
    /// Residual of the returned state: the smallest of the history.  `NaN` if
    /// the pass could not run (non-positive or non-finite `dt`, `omega` or
    /// rest density).
    pub residual: f64,
    /// Whether the residual of the returned state is below the tolerance.
    pub converged: bool,
}

/// The constraint a DFSPH pass enforces.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DfsphPass {
    /// `Dρ/Dt = 0`: no compression rate.
    DivergenceFree,
    /// `ρ* = ρ₀` for the density predicted with the current velocities.
    DensityInvariant,
}

/// The neighbours `(j, |rᵢⱼ|, ∇ᵢWᵢⱼ)` of particle `i`; empty if `i` has no row.
fn neighbor_tuples(
    neighbors: &[Vec<(usize, f64, [f64; 3])>],
    i: usize,
) -> &[(usize, f64, [f64; 3])] {
    neighbors.get(i).map(Vec::as_slice).unwrap_or(&[])
}

/// `Dρᵢ/Dt = Σⱼ mⱼ (vᵢ − vⱼ)·∇ᵢWᵢⱼ` for particle `i`; neighbours outside the
/// arrays are ignored.
fn density_rate(
    i: usize,
    velocities: &[[f64; 3]],
    masses: &[f64],
    neighbors: &[Vec<(usize, f64, [f64; 3])>],
) -> f64 {
    let Some(v_i) = velocities.get(i) else {
        return 0.0;
    };
    let mut rate = 0.0_f64;
    for &(j, _, grad_w) in neighbor_tuples(neighbors, i) {
        let (Some(v_j), Some(&m_j)) = (velocities.get(j), masses.get(j)) else {
            continue;
        };
        rate += m_j
            * ((v_i[0] - v_j[0]) * grad_w[0]
                + (v_i[1] - v_j[1]) * grad_w[1]
                + (v_i[2] - v_j[2]) * grad_w[2]);
    }
    rate
}

/// `1 / (|Σⱼ mⱼ ∇ᵢWᵢⱼ|² + Σⱼ |mⱼ ∇ᵢWᵢⱼ|²)` of the first `n` particles; zero
/// where the denominator vanishes (no neighbours).
fn alpha_coefficients(
    n: usize,
    masses: &[f64],
    neighbors: &[Vec<(usize, f64, [f64; 3])>],
) -> Vec<f64> {
    (0..n)
        .map(|i| {
            let mut sum_squares = 0.0_f64;
            let mut sum = [0.0_f64; 3];
            for &(j, _, grad_w) in neighbor_tuples(neighbors, i) {
                let Some(&m_j) = masses.get(j) else {
                    continue;
                };
                sum_squares += m_j
                    * m_j
                    * (grad_w[0] * grad_w[0] + grad_w[1] * grad_w[1] + grad_w[2] * grad_w[2]);
                for (s, g) in sum.iter_mut().zip(grad_w) {
                    *s += m_j * g;
                }
            }
            let denominator = sum_squares + sum[0] * sum[0] + sum[1] * sum[1] + sum[2] * sum[2];
            if denominator > 0.0 && denominator.is_finite() {
                1.0 / denominator
            } else {
                0.0
            }
        })
        .collect()
}

/// A positive, finite density, or `None`.
fn valid_density(densities: &[f64], i: usize) -> Option<f64> {
    densities
        .get(i)
        .copied()
        .filter(|rho| rho.is_finite() && *rho > 0.0)
}

/// Divergence-Free SPH (DFSPH) pressure solver.
///
/// Implements the two-pass scheme from Bender & Koschier (2015):
///   1. **Divergence-free solve** ([`divergence_free_solve`](Self::divergence_free_solve)) —
///      removes the compression rate `Dρ/Dt` of the velocity field.
///   2. **Density-invariant solve** ([`density_invariant_solve`](Self::density_invariant_solve)) —
///      removes the density excess `ρ* − ρ₀` of the density predicted with the
///      velocities.
///
/// # Discretisation
///
/// The neighbours of a particle are given as `(j, |rᵢⱼ|, ∇ᵢWᵢⱼ)`, see
/// [`neighbor_lists`](Self::neighbor_lists).  With `S_i = Σⱼ mⱼ ∇ᵢWᵢⱼ`
///
/// - `Dρᵢ/Dt = Σⱼ mⱼ (vᵢ − vⱼ)·∇ᵢWᵢⱼ` (positive for converging flow),
/// - `αᵢ = ρᵢ / (|S_i|² + Σⱼ |mⱼ ∇ᵢWᵢⱼ|²)` ([`compute_alpha`](Self::compute_alpha)
///   returns `αᵢ/ρᵢ`), the inverse of the diagonal of the system that links the
///   stiffness `κᵢ` to `Dρᵢ/Dt`,
/// - a stiffness `κᵢ` (pressure `pᵢ = κᵢ ρᵢ`) changes the velocities by
///   `Δvᵢ = −Δt Σⱼ mⱼ (κᵢ/ρᵢ + κⱼ/ρⱼ) ∇ᵢWᵢⱼ`
///   ([`stiffness_accelerations`](Self::stiffness_accelerations)), a symmetric
///   pair force that conserves momentum.
///
/// Each pass is a relaxed Jacobi iteration.  It evaluates the violation of its
/// constraint with the *current* velocities, `κᵢ += ω αᵢ max(Dρᵢ/Dt, 0)/Δt`
/// for the divergence-free pass and `κᵢ += ω αᵢ max(ρ*ᵢ − ρ₀, 0)/Δt²` with
/// `ρ*ᵢ = ρᵢ + Δt Dρᵢ/Dt` for the density-invariant pass, applies the velocity
/// change of the increments, and repeats until the largest violation is below
/// the tolerance.  Only a compression is corrected (an expanding particle,
/// e.g. at a free surface, gets no suction), so the pressures never become
/// negative.
///
/// The iteration is a Jacobi method for a symmetric positive semi-definite
/// system whose diagonal the factors `αᵢ` invert (exactly so for equal
/// masses), with one-sided corrections.  Small relaxation factors approach the
/// constraint monotonically from the compressed side (`ω ≈ 0.3` for a compact
/// cluster of particles, whose scaled system has eigenvalues up to about 4).
/// A factor above the stability limit of Jacobi does not diverge, because an
/// expanding particle is not corrected: the first passes remove the
/// compression and overshoot into expansion.  `ω = 1` is the unrelaxed method
/// of the paper.  The solver returns the state with the smallest residual of
/// those it evaluated, never a worse one than its input.
#[derive(Debug, Clone)]
pub struct DfsphSolverSimple {
    /// Rest density ρ₀ \[kg/m³\].
    pub rest_density: f64,
    /// Relaxation factor ω of the Jacobi update.
    pub omega: f64,
    /// Maximum number of passes of a solve.
    pub max_iter_density: usize,
    /// Tolerance of the divergence-free solve: largest compression rate
    /// `max(Dρ/Dt, 0)/ρ` (1/s).
    pub tol_divergence: f64,
    /// Tolerance of the density-invariant solve: largest density excess
    /// `max(ρ* − ρ₀, 0)/ρ₀` (fraction of ρ₀).
    pub tol_density: f64,
}
impl DfsphSolverSimple {
    /// Create a new `DfsphSolverSimple`.
    pub fn new(
        rest_density: f64,
        omega: f64,
        max_iter_density: usize,
        tol_divergence: f64,
        tol_density: f64,
    ) -> Self {
        Self {
            rest_density,
            omega,
            max_iter_density,
            tol_divergence,
            tol_density,
        }
    }
    /// Neighbour lists `(j, |rᵢⱼ|, ∇ᵢWᵢⱼ)` of the particles at `positions` for
    /// the cubic-spline kernel of smoothing length `h` (support radius `2h`),
    /// in the layout of the other methods of this solver.
    ///
    /// `∇ᵢWᵢⱼ = W'(r) (xᵢ − xⱼ)/r` is the exact gradient with `W' ≤ 0`, so it
    /// points from particle `i` towards `j` and `∇ⱼWⱼᵢ = −∇ᵢWᵢⱼ`.  Row `i`
    /// lists the particles `j ≠ i` with `0 < |rᵢⱼ| < 2h` in ascending order.
    /// The neighbours are found with a spatial hash in `O(N)` expected time.
    pub fn neighbor_lists(positions: &[[f64; 3]], h: f64) -> Vec<Vec<(usize, f64, [f64; 3])>> {
        let neighbors = support_neighbors(positions, h);
        positions
            .iter()
            .enumerate()
            .map(|(i, &x_i)| {
                neighbor_row(&neighbors, i)
                    .iter()
                    .filter_map(|&j| {
                        let x_j = *positions.get(j)?;
                        let (r_ij, r) = separation(x_i, x_j);
                        if j == i || r < MIN_PAIR_DISTANCE || r >= 2.0 * h {
                            return None;
                        }
                        Some((j, r, kernel_gradient(r_ij, r, h)))
                    })
                    .collect()
            })
            .collect()
    }
    /// Pre-compute `1 / (|Σⱼ mⱼ ∇ᵢWᵢⱼ|² + Σⱼ |mⱼ ∇ᵢWᵢⱼ|²)` of every particle,
    /// the DFSPH factor `αᵢ` of Bender & Koschier (2015) divided by `ρᵢ`.
    ///
    /// The factor is the inverse of the diagonal entry of the system that maps
    /// the stiffnesses to the density rates (exactly so for equal masses);
    /// it is zero for a particle without neighbours.
    ///
    /// # Arguments
    /// * `positions` – Particle positions (only their number is used).
    /// * `masses`    – Particle masses.
    /// * `neighbors` – For each particle i, list of `(j, r_ij, ∇ᵢW_ij)`.
    /// * `_h`        – Smoothing length (the gradients already contain it).
    pub fn compute_alpha(
        &self,
        positions: &[[f64; 3]],
        masses: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        _h: f64,
    ) -> Vec<f64> {
        alpha_coefficients(positions.len(), masses, neighbors)
    }
    /// Compute the velocity divergence measure of particle `i`.
    ///
    /// `D_i = (1/ρᵢ) Σⱼ mⱼ (vᵢ − vⱼ)·∇ᵢWᵢⱼ = −∇·v` (positive in compression).
    pub fn velocity_divergence(
        &self,
        i: usize,
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> f64 {
        let rho_i = densities.get(i).copied().unwrap_or(0.0).max(1e-14);
        density_rate(i, velocities, masses, neighbors) / rho_i
    }
    /// The accelerations `aᵢ = −Σⱼ mⱼ (κᵢ/ρᵢ + κⱼ/ρⱼ) ∇ᵢWᵢⱼ` \[m s⁻²\] that the
    /// stiffnesses `κᵢ` \[m² s⁻²\] (pressures `pᵢ = κᵢ ρᵢ`) exert in the pass
    /// iterations of this solver.
    ///
    /// It is the symmetric SPH form of `−∇p/ρ`.  Particles with a
    /// non-positive or non-finite density do not take part; the number of
    /// particles is `stiffness.len()`.
    pub fn stiffness_accelerations(
        &self,
        stiffness: &[f64],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> Vec<[f64; 3]> {
        let specific: Vec<f64> = stiffness
            .iter()
            .enumerate()
            .map(|(i, &kappa)| valid_density(densities, i).map_or(0.0, |rho| kappa / rho))
            .collect();
        specific
            .iter()
            .enumerate()
            .map(|(i, &q_i)| {
                let mut acceleration = [0.0_f64; 3];
                for &(j, _, grad_w) in neighbor_tuples(neighbors, i) {
                    let (Some(&q_j), Some(&m_j)) = (specific.get(j), masses.get(j)) else {
                        continue;
                    };
                    let weight = m_j * (q_i + q_j);
                    for (a, g) in acceleration.iter_mut().zip(grad_w) {
                        *a -= weight * g;
                    }
                }
                acceleration
            })
            .collect()
    }
    /// The compression of every particle for the velocities `velocities`:
    /// `max(Dρ/Dt, 0)` (divergence-free pass, kg m⁻³ s⁻¹) or
    /// `max(ρ + Δt Dρ/Dt − ρ₀, 0)` (density-invariant pass, kg m⁻³), and the
    /// residual `max_i violation_i / ρᵢ` resp. `/ ρ₀` (`NaN` if any value is).
    fn constraint_violation(
        &self,
        pass: DfsphPass,
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        dt: f64,
    ) -> (Vec<f64>, f64) {
        let mut residual = 0.0_f64;
        let violation: Vec<f64> = (0..velocities.len())
            .map(|i| {
                let Some(rho_i) = valid_density(densities, i) else {
                    return 0.0;
                };
                let rate = density_rate(i, velocities, masses, neighbors);
                let (excess, scale) = match pass {
                    DfsphPass::DivergenceFree => (rate, rho_i),
                    DfsphPass::DensityInvariant => {
                        (rho_i + dt * rate - self.rest_density, self.rest_density)
                    }
                };
                if excess.is_nan() {
                    residual = f64::NAN;
                    return 0.0;
                }
                let excess = excess.max(0.0);
                if !residual.is_nan() {
                    residual = residual.max(excess / scale);
                }
                excess
            })
            .collect();
        (violation, residual)
    }
    /// Run one pass (the Jacobi loop described in the type documentation).
    fn solve_pass(
        &self,
        pass: DfsphPass,
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        dt: f64,
    ) -> DfsphPassResult {
        let n = velocities.len();
        let finite_positive = |x: f64| x.is_finite() && x > 0.0;
        if !(finite_positive(dt)
            && finite_positive(self.omega)
            && finite_positive(self.rest_density))
        {
            return DfsphPassResult {
                pressures: vec![0.0; n],
                velocities: velocities.to_vec(),
                iterations: 0,
                residual_history: Vec::new(),
                residual: f64::NAN,
                converged: false,
            };
        }
        let (tolerance, increment_scale) = match pass {
            DfsphPass::DivergenceFree => (self.tol_divergence, 1.0 / dt),
            DfsphPass::DensityInvariant => (self.tol_density, 1.0 / (dt * dt)),
        };
        let alphas = alpha_coefficients(n, masses, neighbors);
        let mut stiffness = vec![0.0_f64; n];
        let mut current = velocities.to_vec();
        let mut history = Vec::new();
        let mut best_residual = f64::INFINITY;
        let mut best_stiffness = stiffness.clone();
        let mut best_velocities = current.clone();
        let mut corrections = 0_usize;
        let mut converged = false;
        loop {
            let (violation, residual) =
                self.constraint_violation(pass, &current, masses, densities, neighbors, dt);
            history.push(residual);
            if !residual.is_finite() {
                break;
            }
            if residual < best_residual {
                best_residual = residual;
                best_stiffness.clone_from(&stiffness);
                best_velocities.clone_from(&current);
            }
            if residual < tolerance {
                converged = true;
                break;
            }
            if corrections >= self.max_iter_density {
                break;
            }
            let increments: Vec<f64> = (0..n)
                .map(|i| match valid_density(densities, i) {
                    Some(rho_i) => self.omega * rho_i * alphas[i] * violation[i] * increment_scale,
                    None => 0.0,
                })
                .collect();
            if increments.iter().all(|&increment| increment == 0.0) {
                break;
            }
            for (kappa, increment) in stiffness.iter_mut().zip(&increments) {
                *kappa += increment;
            }
            let accelerations =
                self.stiffness_accelerations(&increments, masses, densities, neighbors);
            for (v, a) in current.iter_mut().zip(accelerations) {
                for (v_k, a_k) in v.iter_mut().zip(a) {
                    *v_k += dt * a_k;
                }
            }
            corrections += 1;
        }
        let pressures = best_stiffness
            .iter()
            .enumerate()
            .map(|(i, &kappa)| valid_density(densities, i).map_or(0.0, |rho| kappa * rho))
            .collect();
        DfsphPassResult {
            pressures,
            velocities: best_velocities,
            iterations: (corrections + usize::from(converged)).min(self.max_iter_density),
            residual_history: history,
            residual: if best_residual.is_finite() {
                best_residual
            } else {
                f64::NAN
            },
            converged,
        }
    }
    /// **Divergence-free solve** (pass 1 of DFSPH).
    ///
    /// Iterates pressure corrections of the velocities until the compression
    /// rate `max(Dρ/Dt, 0)/ρ` of every particle is below `tol_divergence`
    /// (see the type documentation).  Each iteration changes the velocities
    /// and re-evaluates `Dρ/Dt` from them.
    ///
    /// # Arguments
    /// * `velocities` – Current velocities (not modified; the corrected ones
    ///   are in the result).
    /// * `masses`     – Particle masses.
    /// * `densities`  – Current densities.
    /// * `neighbors`  – Sparse neighbour list `(j, r_ij, ∇ᵢW_ij)`.
    /// * `dt`         – Time step.
    pub fn divergence_free_solve(
        &self,
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        dt: f64,
    ) -> DfsphPassResult {
        self.solve_pass(
            DfsphPass::DivergenceFree,
            velocities,
            masses,
            densities,
            neighbors,
            dt,
        )
    }
    /// **Density-invariant solve** (pass 2 of DFSPH).
    ///
    /// Iterates pressure corrections of the velocities until the density
    /// `ρ* = ρ + Δt Dρ/Dt` predicted with them exceeds the rest density by less
    /// than `tol_density · ρ₀` for every particle.  `velocities` are the
    /// velocities after the non-pressure forces, `densities` the current
    /// densities.
    ///
    /// Arguments as for [`divergence_free_solve`](Self::divergence_free_solve).
    pub fn density_invariant_solve(
        &self,
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        dt: f64,
    ) -> DfsphPassResult {
        self.solve_pass(
            DfsphPass::DensityInvariant,
            velocities,
            masses,
            densities,
            neighbors,
            dt,
        )
    }
    /// **Divergence-free pressure step** (pass 1 of DFSPH).
    ///
    /// The pressures and the number of passes of
    /// [`divergence_free_solve`](Self::divergence_free_solve); use that method
    /// to also get the corrected velocities and the residual history.
    ///
    /// Returns `(pressures, iterations_used)`.
    ///
    /// # Arguments
    /// * `_positions` – Unused: the kernel gradients in `neighbors` carry the geometry.
    /// * `velocities` – Current velocities (not mutated).
    /// * `masses`     – Particle masses.
    /// * `densities`  – Current densities.
    /// * `neighbors`  – Sparse neighbour list `(j, r_ij, ∇ᵢW_ij)`.
    /// * `_h`         – Unused: the kernel gradients in `neighbors` carry the smoothing length.
    /// * `dt`         – Time step.
    pub fn divergence_free_step(
        &self,
        _positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        _h: f64,
        dt: f64,
    ) -> (Vec<f64>, usize) {
        let result = self.divergence_free_solve(velocities, masses, densities, neighbors, dt);
        (result.pressures, result.iterations)
    }
    /// **Density-invariant pressure step** (pass 2 of DFSPH).
    ///
    /// The pressures and the number of passes of
    /// [`density_invariant_solve`](Self::density_invariant_solve); `velocities`
    /// are the velocities after the non-pressure forces.
    ///
    /// Returns `(pressures, iterations_used)`; arguments as for
    /// [`divergence_free_step`](Self::divergence_free_step).
    pub fn density_invariant_step(
        &self,
        _positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        densities: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
        _h: f64,
        dt: f64,
    ) -> (Vec<f64>, usize) {
        let result = self.density_invariant_solve(velocities, masses, densities, neighbors, dt);
        (result.pressures, result.iterations)
    }
}
impl DfsphSolverSimple {
    /// Compute the density source term for particle `i` (DFSPH, Bender et al. 2015).
    ///
    /// The source term is the Lagrangian time derivative of density:
    ///   `s_i = Dρ_i/Dt = sum_j m_j (v_i - v_j) · ∇W_ij`
    ///
    /// A positive value means the local density is increasing (compression).
    ///
    /// # Arguments
    /// * `i`          – Particle index.
    /// * `velocities` – Velocity array.
    /// * `masses`     – Mass array.
    /// * `neighbors`  – For each particle i, list of `(j, r_ij, grad_W_ij)`.
    pub fn compute_source_term(
        &self,
        i: usize,
        velocities: &[[f64; 3]],
        masses: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> f64 {
        density_rate(i, velocities, masses, neighbors)
    }
    /// Compute the source terms for all particles.
    ///
    /// Convenience wrapper that calls [`compute_source_term`](Self::compute_source_term)
    /// for every particle index.
    pub fn compute_all_source_terms(
        &self,
        velocities: &[[f64; 3]],
        masses: &[f64],
        neighbors: &[Vec<(usize, f64, [f64; 3])>],
    ) -> Vec<f64> {
        (0..velocities.len())
            .map(|i| self.compute_source_term(i, velocities, masses, neighbors))
            .collect()
    }
}
/// Framework for comparing pressure solver performance.
pub struct SolverComparison {
    /// Rest density.
    pub rho0: f64,
    /// Speed of sound (for WCSPH).
    pub c0: f64,
    /// Tait exponent.
    pub gamma: f64,
    /// PCISPH delta.
    pub pcisph_delta: f64,
    /// IISPH relaxation.
    pub iisph_omega: f64,
    /// Maximum iterations for iterative solvers.
    pub max_iter: usize,
    /// Convergence tolerance.
    pub tolerance: f64,
}
impl SolverComparison {
    /// Create a comparison framework with default parameters.
    pub fn new(rho0: f64, c0: f64) -> Self {
        Self {
            rho0,
            c0,
            gamma: 7.0,
            pcisph_delta: 0.5,
            iisph_omega: 0.5,
            max_iter: 100,
            tolerance: 0.001,
        }
    }
    /// Run WCSPH solver on the given densities.
    pub fn run_wcsph(&self, densities: &[f64]) -> SolverBenchmarkResult {
        let solver = WcSphSolver::new(self.rho0, self.c0, self.gamma);
        let mut pressures = vec![0.0; densities.len()];
        solver.compute_all_pressures(densities, &mut pressures);
        let max_err = densities
            .iter()
            .map(|&rho| (rho - self.rho0).abs())
            .fold(0.0_f64, f64::max);
        let avg_err = if densities.is_empty() {
            0.0
        } else {
            densities
                .iter()
                .map(|&rho| (rho - self.rho0).abs())
                .sum::<f64>()
                / densities.len() as f64
        };
        SolverBenchmarkResult {
            solver_type: SolverType::Wcsph,
            iterations: 0,
            max_density_error: max_err,
            avg_density_error: avg_err,
            pressures,
        }
    }
    /// Run PCISPH solver on densities predicted without pressure.
    ///
    /// The density errors of the result are those left after the pressure
    /// correction, evaluated with the lattice response of `pcisph_delta`
    /// ([`pcisph_lattice_response`]).
    pub fn run_pcisph(&self, predicted_densities: &[f64]) -> SolverBenchmarkResult {
        let solver = PcisphSolverSimple {
            rho0: self.rho0,
            delta: self.pcisph_delta,
            max_iter: self.max_iter,
            tolerance: self.tolerance,
        };
        let (pressures, iters) = solver.solve(predicted_densities);
        let corrected = pcisph_lattice_response(predicted_densities, &pressures, solver.delta);
        let max_err = corrected
            .iter()
            .map(|&rho| (rho - self.rho0).abs())
            .fold(0.0_f64, f64::max);
        let avg_err = if corrected.is_empty() {
            0.0
        } else {
            corrected
                .iter()
                .map(|&rho| (rho - self.rho0).abs())
                .sum::<f64>()
                / corrected.len() as f64
        };
        SolverBenchmarkResult {
            solver_type: SolverType::Pcisph,
            iterations: iters,
            max_density_error: max_err,
            avg_density_error: avg_err,
            pressures,
        }
    }
    /// Run IISPH solver on a pre-assembled PPE system.
    pub fn run_iisph(&self, rhs: &[f64], aij: &[Vec<(usize, f64)>]) -> SolverBenchmarkResult {
        let solver = IisphSolverSimple {
            rho0: self.rho0,
            omega: self.iisph_omega,
            max_iter: self.max_iter,
            tolerance: self.tolerance,
        };
        let (pressures, iters, residual) = solver.solve_pressure_poisson(rhs, aij);
        SolverBenchmarkResult {
            solver_type: SolverType::Iisph,
            iterations: iters,
            max_density_error: residual,
            avg_density_error: residual,
            pressures,
        }
    }
}
/// History entry for solver performance tracking.
#[derive(Debug, Clone)]
pub struct SolverPerformanceEntry {
    /// Solver type used.
    pub solver_type: SolverType,
    /// Number of iterations.
    pub iterations: usize,
    /// Final residual.
    pub residual: f64,
}
/// Full PCISPH solver (Solenthaler & Pajarola 2009) operating on plain arrays.
///
/// Unlike [`PcisphSolverSimple`], this struct maintains a [`PcisphState`] and
/// exposes separate prediction, error-computation, and correction methods so
/// that callers can interleave SPH density summation with the iterative loop.
#[derive(Debug, Clone)]
pub struct PcisphSolver {
    /// Rest density ρ₀ \[kg/m³\].
    pub rest_density: f64,
    /// Pre-computed stiffness (δ) parameter.
    pub delta: f64,
    /// Maximum number of correction iterations.
    pub max_iter: usize,
    /// Density error threshold η (fraction of ρ₀).
    pub eta: f64,
}
/// Outcome of [`PcisphSolver::predict_correct`].
#[derive(Debug, Clone)]
pub struct PcisphStepResult {
    /// Pressure `pᵢ` of every particle \[Pa\]; never negative.
    pub pressures: Vec<f64>,
    /// Pressure accelerations `aᵢ = −Σⱼ mⱼ (pᵢ/ρ*ᵢ² + pⱼ/ρ*ⱼ²) ∇W(x*ᵢ − x*ⱼ)`
    /// that belong to `pressures` \[m s⁻²\].
    pub accelerations: Vec<[f64; 3]>,
    /// The prediction the loop ended with: positions, velocities and densities
    /// predicted with the non-pressure forces and `accelerations`; the
    /// `pressure_corrections` are the increments `δ (ρ* − ρ₀)` of the last
    /// pass (before the clamping of the pressure at zero).
    pub state: PcisphState,
    /// Number of passes of the loop (at most `max_iter`); the pass that
    /// finds the density error below the threshold counts as well.
    pub iterations: usize,
    /// Largest density error `max_i |ρ*ᵢ − ρ₀|` of every evaluated prediction
    /// \[kg/m³\] that the pressure can still act on (see
    /// [`PcisphSolver::predict_correct`]).  Entry 0 is the prediction without
    /// pressure, entry `k` the one after `k` corrections.
    pub density_error_history: Vec<f64>,
    /// Whether the final density error is below `eta · ρ₀`.
    pub converged: bool,
}

impl PcisphSolver {
    /// Construct a `PcisphSolver` for particles of mass `mass`, smoothing
    /// length `h` and time step `dt`.
    ///
    /// `delta` is the lattice-based pressure-correction factor
    /// [`pcisph_delta`] of Solenthaler & Pajarola (2009, §4.1).  It scales
    /// with `1/dt²` and depends on the mass: call
    /// [`update_delta`](Self::update_delta) when the time step changes.
    pub fn new(rest_density: f64, h: f64, dt: f64, mass: f64, max_iter: usize, eta: f64) -> Self {
        Self {
            rest_density,
            delta: pcisph_delta(rest_density, h, dt, mass),
            max_iter,
            eta,
        }
    }
    /// Recompute `delta` for a new smoothing length, time step or particle mass.
    pub fn update_delta(&mut self, h: f64, dt: f64, mass: f64) {
        self.delta = pcisph_delta(self.rest_density, h, dt, mass);
    }
    /// Predict velocities and positions for all particles given current forces.
    ///
    /// `predicted_v = v + (F/m) * dt`
    /// `predicted_x = x + predicted_v * dt`
    pub fn predict_velocities_positions(
        &self,
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        forces: &[[f64; 3]],
        masses: &[f64],
        dt: f64,
        state: &mut PcisphState,
    ) {
        let n = positions.len();
        for i in 0..n {
            let inv_m = 1.0 / masses[i].max(1e-30);
            let mut pv = [0.0_f64; 3];
            for k in 0..3 {
                pv[k] = velocities[i][k] + forces[i][k] * inv_m * dt;
                state.predicted_velocities[i][k] = pv[k];
                state.predicted_positions[i][k] = positions[i][k] + pv[k] * dt;
            }
        }
    }
    /// Compute density errors: `ρ_pred - ρ₀` for each particle.
    pub fn compute_density_error(&self, state: &PcisphState) -> Vec<f64> {
        state
            .predicted_densities
            .iter()
            .map(|&rho| rho - self.rest_density)
            .collect()
    }
    /// Compute per-particle pressure corrections: `δP_i = delta * (ρ_pred - ρ₀)`.
    ///
    /// Corrections are stored in `state.pressure_corrections`.
    pub fn compute_pressure_correction(&self, state: &mut PcisphState) {
        for i in 0..state.len() {
            let err = state.predicted_densities[i] - self.rest_density;
            state.pressure_corrections[i] = self.delta * err;
        }
    }
    /// Check convergence: `max |ρ_err| / ρ₀ < eta`.
    pub fn converged(&self, errors: &[f64]) -> bool {
        errors.iter().map(|e| e.abs()).fold(0.0_f64, f64::max) < self.eta * self.rest_density
    }
    /// Predicted densities `ρ*ᵢ = mᵢ W(0, h) + Σⱼ mⱼ W(|x*ᵢ − x*ⱼ|, h)` of the
    /// predicted positions of `state`, stored in `state.predicted_densities`.
    ///
    /// The neighbour lists are those of the beginning of the step; a particle
    /// that is not in `neighbors` is isolated, a listed particle outside the
    /// state and `i` itself are ignored.
    pub fn predict_densities(
        &self,
        masses: &[f64],
        neighbors: &[Vec<usize>],
        h: f64,
        state: &mut PcisphState,
    ) {
        let n = state.len();
        let kernel = CubicSplineKernel;
        let densities: Vec<f64> = state
            .predicted_positions
            .iter()
            .enumerate()
            .map(|(i, &x_i)| {
                let mut rho = masses.get(i).map_or(0.0, |&m_i| m_i * kernel.w(0.0, h));
                for &j in neighbors.get(i).map_or(&[][..], Vec::as_slice) {
                    if j == i || j >= n {
                        continue;
                    }
                    let (Some(&m_j), Some(&x_j)) =
                        (masses.get(j), state.predicted_positions.get(j))
                    else {
                        continue;
                    };
                    rho += m_j * kernel.w(separation(x_i, x_j).1, h);
                }
                rho
            })
            .collect();
        state.predicted_densities = densities;
    }
    /// Pressure accelerations `aᵢ = −Σⱼ mⱼ (pᵢ/ρ*ᵢ² + pⱼ/ρ*ⱼ²) ∇W(x*ᵢ − x*ⱼ)`
    /// \[m s⁻²\] of the pressures `pressures` on the predicted configuration
    /// (positions and densities) of `state`.
    ///
    /// The pair force is symmetric, so the total momentum `Σ mᵢ aᵢ` vanishes
    /// for symmetric neighbour lists.  Particles with a non-positive predicted
    /// density do not take part.
    pub fn pressure_accelerations(
        &self,
        masses: &[f64],
        pressures: &[f64],
        neighbors: &[Vec<usize>],
        h: f64,
        state: &PcisphState,
    ) -> Vec<[f64; 3]> {
        let n = state.len();
        let specific = |i: usize| -> Option<f64> {
            let rho = *state.predicted_densities.get(i)?;
            let p = *pressures.get(i)?;
            if rho > 0.0 && rho.is_finite() {
                Some(p / (rho * rho))
            } else {
                None
            }
        };
        state
            .predicted_positions
            .iter()
            .enumerate()
            .map(|(i, &x_i)| {
                let mut acceleration = [0.0_f64; 3];
                let Some(p_i) = specific(i) else {
                    return acceleration;
                };
                for &j in neighbors.get(i).map_or(&[][..], Vec::as_slice) {
                    if j == i || j >= n {
                        continue;
                    }
                    let (Some(p_j), Some(&m_j), Some(&x_j)) =
                        (specific(j), masses.get(j), state.predicted_positions.get(j))
                    else {
                        continue;
                    };
                    let (r_ij, r) = separation(x_i, x_j);
                    if r < MIN_PAIR_DISTANCE || r >= 2.0 * h {
                        continue;
                    }
                    let weight = m_j * (p_i + p_j);
                    let grad_w = kernel_gradient(r_ij, r, h);
                    for (a, g) in acceleration.iter_mut().zip(grad_w) {
                        *a -= weight * g;
                    }
                }
                acceleration
            })
            .collect()
    }
    /// Full PCISPH prediction-correction loop (Solenthaler & Pajarola 2009).
    ///
    /// Starting from `p = 0`, every pass
    ///   1. takes the predicted positions `x*` and velocities `v*` of the
    ///      previous pass (first pass: predicted with the non-pressure forces
    ///      only) and the densities `ρ*ᵢ = mᵢ W(0, h) + Σⱼ mⱼ W(|x*ᵢ − x*ⱼ|, h)`
    ///      summed from them,
    ///   2. stops if the density error is below `eta · ρ₀`,
    ///   3. otherwise updates the pressures, `pᵢ ← max(0, pᵢ + δ (ρ*ᵢ − ρ₀))`,
    ///   4. evaluates the pressure accelerations of these pressures on the
    ///      predicted configuration, `aᵢ = −Σⱼ mⱼ (pᵢ/ρ*ᵢ² + pⱼ/ρ*ⱼ²) ∇W(x*ᵢ − x*ⱼ)`,
    ///      and predicts `v* = v + Δt (F/m + a)`, `x* = x + Δt v*` again.
    ///
    /// The pressure is never negative, so the density error that counts is
    /// `|ρ* − ρ₀|` for particles with positive pressure and `max(ρ* − ρ₀, 0)`
    /// for the others: a particle with a deficient neighbourhood (free surface)
    /// and zero pressure is not a violation.  `delta` has to match the time
    /// step and the particle mass, see [`pcisph_delta`] and
    /// [`update_delta`](Self::update_delta); with `delta`, `dt` or `h` not
    /// positive and finite no correction is possible and the loop stops after
    /// evaluating the prediction without pressure.
    ///
    /// Inputs of different lengths (`velocities`, `masses` or
    /// `non_pressure_forces` not matching `positions`) give an empty result
    /// with zero pressures and no iteration.
    ///
    /// # Arguments
    /// * `positions`   – Current particle positions.
    /// * `velocities`  – Current particle velocities.
    /// * `masses`      – Particle masses.
    /// * `non_pressure_forces` – Forces excluding pressure (gravity, viscosity, etc.).
    /// * `neighbors`   – For each particle `i`, the indices `j ≠ i` within the
    ///   support radius `2h` (plus a skin for the motion of the step).
    /// * `h`           – Smoothing length.
    /// * `dt`          – Time step.
    pub fn predict_correct(
        &self,
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        non_pressure_forces: &[[f64; 3]],
        neighbors: &[Vec<usize>],
        h: f64,
        dt: f64,
    ) -> PcisphStepResult {
        let n = positions.len();
        let mut state = PcisphState::new(n);
        let mut pressures = vec![0.0_f64; n];
        let mut accelerations = vec![[0.0_f64; 3]; n];
        let mut history = Vec::new();
        if velocities.len() != n || masses.len() != n || non_pressure_forces.len() != n {
            return PcisphStepResult {
                pressures,
                accelerations,
                state,
                iterations: 0,
                density_error_history: history,
                converged: false,
            };
        }
        let finite_positive = |x: f64| x.is_finite() && x > 0.0;
        let usable = finite_positive(h) && finite_positive(dt) && finite_positive(self.delta);
        let max_corrections = if usable { self.max_iter } else { 0 };
        let tolerance = self.eta * self.rest_density;
        let predict = |accelerations: &[[f64; 3]], state: &mut PcisphState| {
            let forces: Vec<[f64; 3]> = non_pressure_forces
                .iter()
                .zip(accelerations)
                .zip(masses)
                .map(|((f, a), &m)| [f[0] + m * a[0], f[1] + m * a[1], f[2] + m * a[2]])
                .collect();
            self.predict_velocities_positions(positions, velocities, &forces, masses, dt, state);
            self.predict_densities(masses, neighbors, h, state);
        };
        predict(&accelerations, &mut state);
        let mut corrections = 0_usize;
        let mut converged = false;
        loop {
            let residual = max_propagating_nan(
                self.compute_density_error(&state)
                    .into_iter()
                    .zip(&pressures)
                    .map(|(error, &p)| projected_density_error(error, p)),
            );
            history.push(residual);
            if !residual.is_finite() {
                break;
            }
            if residual < tolerance {
                converged = true;
                break;
            }
            if corrections >= max_corrections {
                break;
            }
            self.compute_pressure_correction(&mut state);
            for (p, correction) in pressures.iter_mut().zip(&state.pressure_corrections) {
                *p = (*p + correction).max(0.0);
            }
            accelerations = self.pressure_accelerations(masses, &pressures, neighbors, h, &state);
            predict(&accelerations, &mut state);
            corrections += 1;
        }
        PcisphStepResult {
            pressures,
            accelerations,
            state,
            iterations: (corrections + usize::from(converged)).min(self.max_iter),
            density_error_history: history,
            converged,
        }
    }
    /// Full PCISPH prediction-correction loop (Solenthaler & Pajarola 2009).
    ///
    /// The pressures and the number of passes of
    /// [`predict_correct`](Self::predict_correct), which also returns the
    /// predicted state, the pressure accelerations and the history of the
    /// density error; see there for the algorithm and the arguments.
    ///
    /// Returns `(pressures, iterations_used)`.
    pub fn predict_correct_step(
        &self,
        positions: &[[f64; 3]],
        velocities: &[[f64; 3]],
        masses: &[f64],
        non_pressure_forces: &[[f64; 3]],
        neighbors: &[Vec<usize>],
        h: f64,
        dt: f64,
    ) -> (Vec<f64>, usize) {
        let result = self.predict_correct(
            positions,
            velocities,
            masses,
            non_pressure_forces,
            neighbors,
            h,
            dt,
        );
        (result.pressures, result.iterations)
    }
}
impl PcisphSolver {
    /// Compute a corrected velocity for particle `i` from its pressure correction.
    ///
    /// In PCISPH, once the pressure correction ΔP_i is known, the corrected
    /// acceleration on particle `i` is:
    ///   `a_corr_i = -sum_j m_j * (ΔP_i/ρ_i² + ΔP_j/ρ_j²) * ∇W_ij`
    ///
    /// For a simplified single-particle update with a scalar pressure gradient
    /// (suitable for testing/educational use):
    ///   `v_corr_i = v_pred_i + dt * (-ΔP_i / (rho_i * h)) * n_hat`
    ///
    /// where `n_hat` is the pressure gradient direction (normalized).
    ///
    /// # Arguments
    /// * `v_predicted`        – Predicted velocity of particle i \[m/s\].
    /// * `pressure_correction` – Scalar pressure correction ΔP_i \[Pa\].
    /// * `rho_i`              – Predicted density of particle i \[kg/m³\].
    /// * `h`                  – Smoothing length \[m\].
    /// * `dt`                 – Time step \[s\].
    /// * `gradient_dir`       – Unit direction of the local pressure gradient.
    pub fn compute_predicted_velocity_correction(
        &self,
        v_predicted: [f64; 3],
        pressure_correction: f64,
        rho_i: f64,
        h: f64,
        dt: f64,
        gradient_dir: [f64; 3],
    ) -> [f64; 3] {
        let rho = rho_i.max(1e-14);
        let h = h.max(1e-30);
        let scale = -pressure_correction * dt / (rho * h);
        [
            v_predicted[0] + scale * gradient_dir[0],
            v_predicted[1] + scale * gradient_dir[1],
            v_predicted[2] + scale * gradient_dir[2],
        ]
    }
}
/// Diagonal (Jacobi) preconditioner for the IISPH pressure Poisson system.
///
/// Stores the precomputed diagonal coefficients `a_ii` and provides a
/// preconditioned Jacobi step that is more stable than raw Jacobi at high
/// relaxation factors.
#[derive(Debug, Clone)]
pub struct IisphDiagonalPreconditioner {
    /// Precomputed diagonal coefficients (a_ii for each particle).
    pub diag: Vec<f64>,
    /// Relaxation factor ω.
    pub omega: f64,
    /// Rest density ρ₀ for convergence checking.
    pub rho0: f64,
}
impl IisphDiagonalPreconditioner {
    /// Build the preconditioner from the off-diagonal system.
    pub fn build(aij: &[Vec<(usize, f64)>], omega: f64, rho0: f64) -> Self {
        let diag: Vec<f64> = aij
            .iter()
            .map(|row| -row.iter().map(|&(_, a)| a).sum::<f64>())
            .collect();
        Self { diag, omega, rho0 }
    }
    /// One preconditioned Jacobi step.
    ///
    /// Returns `(p_new, max_residual)`.
    pub fn step(&self, p: &[f64], rhs: &[f64], aij: &[Vec<(usize, f64)>]) -> (Vec<f64>, f64) {
        let n = p.len();
        let mut p_new = vec![0.0_f64; n];
        let mut max_res = 0.0_f64;
        for i in 0..n {
            let aii = self.diag[i];
            if aii.abs() < 1e-20 {
                p_new[i] = p[i];
                continue;
            }
            let off: f64 = aij[i].iter().map(|&(j, a)| a * p[j]).sum();
            let target = (rhs[i] - off) / aii;
            p_new[i] = ((1.0 - self.omega) * p[i] + self.omega * target).max(0.0);
            let res = (aii * p_new[i] + off - rhs[i]).abs();
            if res > max_res {
                max_res = res;
            }
        }
        (p_new, max_res)
    }
    /// Run until convergence or `max_iter` steps.
    pub fn solve(
        &self,
        rhs: &[f64],
        aij: &[Vec<(usize, f64)>],
        max_iter: usize,
        tol: f64,
    ) -> (Vec<f64>, usize, f64) {
        let n = rhs.len();
        let mut p = vec![0.0_f64; n];
        let mut residual = f64::MAX;
        for iter in 0..max_iter {
            let (p_new, res) = self.step(&p, rhs, aij);
            p = p_new;
            residual = res;
            if residual < tol * self.rho0 {
                return (p, iter + 1, residual);
            }
        }
        (p, max_iter, residual)
    }
}
/// A family of Tait equation of state variants parameterized by rest density,
/// sound speed, and exponent.
#[derive(Debug, Clone)]
pub struct TaitEosFamily {
    /// Rest density ρ₀ \[kg/m³\].
    pub rho0: f64,
    /// Speed of sound c₀ \[m/s\].
    pub c0: f64,
    /// Exponent γ (7 for water, 1.4 for ideal gas).
    pub gamma: f64,
    /// Bulk modulus B = ρ₀ c₀² / γ.
    pub big_b: f64,
}
impl TaitEosFamily {
    /// Create a new EOS family.
    pub fn new(rho0: f64, c0: f64, gamma: f64) -> Self {
        let big_b = rho0 * c0 * c0 / gamma;
        Self {
            rho0,
            c0,
            gamma,
            big_b,
        }
    }
    /// Standard water EOS (ρ₀=1000, c₀=100, γ=7).
    pub fn water() -> Self {
        Self::new(1000.0, 100.0, 7.0)
    }
    /// Ideal gas EOS (ρ₀=1.2, c₀=343, γ=1.4).
    pub fn air() -> Self {
        Self::new(1.2, 343.0, 1.4)
    }
    /// Pressure from density.
    pub fn pressure(&self, rho: f64) -> f64 {
        self.big_b * ((rho / self.rho0).powf(self.gamma) - 1.0)
    }
    /// Density from pressure (inverse Tait).
    pub fn density_from_pressure(&self, p: f64) -> f64 {
        self.rho0 * (p / self.big_b + 1.0).powf(1.0 / self.gamma)
    }
    /// Local speed of sound at density `rho`: c = c₀ (ρ/ρ₀)^((γ-1)/2).
    pub fn sound_speed(&self, rho: f64) -> f64 {
        self.c0 * (rho / self.rho0).powf((self.gamma - 1.0) / 2.0)
    }
    /// CFL timestep: `dt_cfl = 0.4 h / c(ρ)`.
    pub fn cfl_dt(&self, h: f64, rho: f64) -> f64 {
        0.4 * h / self.sound_speed(rho).max(1e-20)
    }
    /// Pressure for all particles in-place.
    pub fn compute_all(&self, densities: &[f64], pressures: &mut [f64]) {
        for (p_out, &rho) in pressures.iter_mut().zip(densities.iter()) {
            *p_out = self.pressure(rho);
        }
    }
    /// Maximum safe time step across all densities.
    pub fn min_cfl_dt(&self, h: f64, densities: &[f64]) -> f64 {
        densities
            .iter()
            .map(|&rho| self.cfl_dt(h, rho))
            .fold(f64::INFINITY, f64::min)
    }
}
